# Salinax sculpted from nothing on the skeleton and clips of the game's own export of it (sculptkit.py), grown from
# sarel.py (its salt colours, its cut blocks and its sleepy eye):
#   blender --background --factory-startup --python sculpts/salinax.py -- <the export's Salinax.glb> <out.glb>
#
# Carpathia No. 10134, the Salt Hall Pokemon (plan 46, CP-dex-3, "134. Salinax: the salt mine guardian"); no sculptor
# in the game, so its export is a biped generated by rule: only its skeleton, its clips and its size are taken.
# From the picture: a great beast of banded rock salt on four thick legs, striped all over in white, grey, pink and
# amber like a salt mine's walls; a long blocky barrel of a body, on its back a raised rim of salt round a pool of pale
# brine; a domed head low at the front, its face white, with two sleepy half-shut eyes, a wide calm mouth and two small
# teeth standing up at its corners; a cluster of clear cube crystals on each shoulder; legs of stacked blocks, the
# front pair the thicker, ending in blunt toes. The grains of salt about it are a drawn effect and are left out.
#
# The skeleton is a biped's: the front legs are hung on the arms (their joints at the shoulders), the hind legs on the
# legs, the head on the head; the shoulder crystals stay on the body (the arms swing up to 99 degrees about their
# joints in the clips, which would throw them off the shoulders); the ear bones carry nothing.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import Kit, ell, srgb, unit, args, hull, slab, polygon, inside, boxy, lathe, sibling

s = sibling("sarel")

WHITE, GREY, PINK, AMBER = "#F2EDEA", "#C7C3C0", "#E3A8A2", "#D8923C"
TOE, CRYS, CRYS_DK, BRINE, MOUTH, TOOTH = "#DAD4D2", "#E8F0F6", "#C4D6E4", "#B8DDEA", "#4A3230", "#F6F2EE"

HEAD_C, HEAD_R = np.array([0.0, -0.41, 0.56]), np.array([0.2, 0.18, 0.19])
FACE_Y = HEAD_C[1] - HEAD_R[1]
EYE_X, EYE_Z, EYE_HALF = 0.075, 0.6, (0.046, 0.036)
SLOT = 0.042                      # the height of one band
SEQ = [WHITE, PINK, WHITE, GREY, WHITE, AMBER, GREY, WHITE, PINK, AMBER]


def band_masks(exclude):
    """One paint mask a colour of the bands, wavy across the body; exclude(P) keeps the face white."""
    N = len(SEQ)
    def t_of(P):
        return P[:, 2] / SLOT + 0.35 * np.sin(P[:, 0] * 8 + P[:, 1] * 6) + 0.2 * np.sin(P[:, 1] * 15 - P[:, 0] * 5)
    out = []
    for j, col in enumerate(SEQ):
        if col == WHITE:
            continue
        out.append((lambda P, j=j: inside(np.abs(np.mod(t_of(P) - j, N) - 0.5) - 0.42, 0.06) * (1 - exclude(P)), col))
    return out


def face_zone(P):
    return (inside(P[:, 1] - (HEAD_C[1] - 0.04), 0.01) * inside(0.44 - P[:, 2], 0.01) * inside(P[:, 2] - 0.7, 0.01)
            * inside(np.abs(P[:, 0]) - 0.17, 0.01))


def body(k):
    k.add("trunk", ell((0.0, 0.05, 0.56), (0.29, 0.38, 0.29), deform=boxy(3.2)), WHITE, "body")
    k.add("chest", ell((0.0, -0.2, 0.5), (0.28, 0.2, 0.25), deform=boxy(3.0)), WHITE, "body")
    k.add("rump", ell((0.0, 0.28, 0.5), (0.26, 0.15, 0.25), deform=boxy(3.0)), WHITE, "body")


def head(k):
    k.add("head", ell(HEAD_C, HEAD_R, deform=boxy(2.6)), WHITE, "head")
    k.add("brow", ell(HEAD_C + (0, 0.02, 0.07), (0.17, 0.15, 0.13)), WHITE, "head")


def legs(k):
    # front legs: two stacked blocks each, fused into the shoulders, on the arms
    for nm, bone, (x, y), r, z in (("fleg", "arm{s}", (0.225, -0.2), 0.12, 0.0), ("hleg", "leg{s}", (0.22, 0.28), 0.115, 0.0)):
        k.add(nm + "up", ell((x, y, 0.37), (r, r, 0.17), deform=boxy(3.2)), WHITE, bone, mirror=True)
        k.add(nm + "low", ell((x + 0.005, y - 0.01, 0.13), (r * 1.03, r * 1.03, 0.13), deform=boxy(3.6)), WHITE, bone,
              mirror=True)
        # the blunt toes in front of each foot
        for i, dx in enumerate((-0.07, 0.0, 0.07)):
            c = np.array([x + dx, y - r - 0.01, 0.045])
            k.add(f"{nm}toe{i}", s.block(c - (0.033, 0.035, 0.045), c + (0.033, 0.035, 0.04), cham=0.35), TOE, bone,
                  fuse=False, mirror=True, surface="shell")


def pool(k):
    """The raised rim of salt round the pool of brine on the back: three hexagonal rings in bands, the water in them."""
    c = np.array([0.0, 0.08, 0.0])
    for i, (z0, z1, col) in enumerate(((0.79, 0.835, PINK), (0.835, 0.875, WHITE), (0.875, 0.915, GREY))):
        # a ring: the profile closed back to its first point (lathe joins the rows in order)
        prof = [(0.19, z0), (0.27, z0), (0.27 - 0.01 * i, z1), (0.19, z1), (0.19, z0)]
        V, F = lathe(c, (0, 0, 1), prof, seg=6)
        V = V * np.array([1.0, 1.35, 1.0]) + np.array([0, c[1] * -0.35, 0])
        k.add(f"rim{i}", (V, F), col, "body", fuse=False, surface="shell")
    V, F = lathe(c, (0, 0, 1), [(0.0, 0.82), (0.2, 0.82), (0.2, 0.87), (0.0, 0.87)], seg=6)
    k.add("brine", (V * np.array([1.0, 1.35, 1.0]) + np.array([0, c[1] * -0.35, 0]), F), BRINE, "body", fuse=False,
          surface="plastic")


def crystals(k):
    """A cluster of clear cube crystals on each shoulder, leaning out."""
    for i, (c, h, rot, col) in enumerate((
            ((0.25, -0.2, 0.82), (0.07, 0.07, 0.08), (12, -20, 25), CRYS),
            ((0.265, -0.1, 0.79), (0.05, 0.05, 0.055), (-10, -30, 10), CRYS_DK),
            ((0.22, -0.3, 0.77), (0.042, 0.042, 0.045), (20, 10, 40), CRYS),
            ((0.28, -0.26, 0.75), (0.035, 0.035, 0.035), (5, -15, 5), CRYS_DK))):
        c = np.array(c); h = np.array(h)
        k.add(f"crystal{i}", s.block(c - h, c + h, rot, cham=0.12), col, "body", fuse=False, mirror=True,
              surface="plastic")


def face(k):
    # the wide calm mouth, a little curved, and two small teeth up from its corners
    k.decal((0.0, FACE_Y + 0.02, 0.495), (0, -1, -0.05), (0.125, 0.017), MOUTH, eps=0.003, rings=6, segs=48,
            outline=polygon([(-1, 0.3), (-0.5, -0.1), (0.5, -0.1), (1, 0.3), (1, 0.9), (0.5, 0.6), (-0.5, 0.6),
                             (-1, 0.9)]))
    for sx in (1, -1):
        b = np.array([sx * 0.088, FACE_Y + 0.028, 0.485])
        pts = [b + (0.02, 0, 0), b - (0.02, 0, 0), b + (0, 0.02, 0), b + (0, -0.02, 0),
               b + (0.004 * sx, -0.01, 0.05)]
        k.add(f"tooth{'RL'[sx < 0]}", hull(pts), TOOTH, "head", fuse=False, surface="shell")


def salinax(src, out):
    k = Kit(src, coat="shell")
    body(k)
    head(k)
    legs(k)
    pool(k)
    crystals(k)
    for mask, col in band_masks(face_zone):
        k.paint(mask, col)
    face(k)
    k.build(voxel=0.0085, smooth=3, band=0.006)
    eye = s.sleepy_open(lid=WHITE)
    k.eye_states(s.lay_sleepy(k, (EYE_X, FACE_Y + 0.01, EYE_Z), unit(0.25, -1, 0.05), EYE_HALF, WHITE, look=eye))
    k.export(out)


if __name__ == "__main__":
    salinax(*args())
